#!/usr/bin/env python3
"""Export a language's untranslated entries to JSON, and fill them back.

  po_todo.py export <lang> <out.json>
  po_todo.py fill <lang> <in.json>

Works on src/slic3r/GUI/JusPrin/Localization/{native,pages}/<lang>.po, which
are written --no-wrap (one line per field).

The JSON is a list of {"catalog", "key", "msgctxt", "msgid", "msgid_plural",
"comments", "nplurals", "msgstr": [..], "review": ""}. Fill writes msgstr,
adds "# AI Translated", and "# Needs human review: <review>" when review is
non-empty.
"""
import json
import re
import sys
from pathlib import Path

LOC = Path("/Users/kenneth/Projects/JusPrin/.claude/worktrees/upbeat-bhaskara-091e6c/src/slic3r/GUI/JusPrin/Localization")


def unquote(line, prefix):
    raw = line[len(prefix):].strip()
    assert raw.startswith('"') and raw.endswith('"'), line
    return json.loads(raw)  # PO escapes match JSON's for \n \t \" \\


def quote(text):
    return '"' + text.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n").replace("\t", "\\t") + '"'


def parse(path):
    blocks = path.read_text(encoding="utf-8").split("\n\n")
    entries = []
    for index, block in enumerate(blocks):
        lines = block.strip("\n").split("\n")
        e = {"index": index, "comments": [], "msgctxt": None, "msgid": None, "msgid_plural": None, "msgstr": [], "obsolete": False}
        for line in lines:
            if line.startswith("#~"):
                e["obsolete"] = True
            elif line.startswith("#"):
                e["comments"].append(line)
            elif line.startswith("msgctxt "):
                e["msgctxt"] = unquote(line, "msgctxt ")
            elif line.startswith("msgid_plural "):
                e["msgid_plural"] = unquote(line, "msgid_plural ")
            elif line.startswith("msgid "):
                e["msgid"] = unquote(line, "msgid ")
            elif line.startswith("msgstr["):
                e["msgstr"].append(unquote(line, line[: line.index("]") + 1] + " "))
            elif line.startswith("msgstr "):
                e["msgstr"].append(unquote(line, "msgstr "))
            elif line.startswith('"'):
                raise SystemExit(f"{path}: wrapped line in block {index}: {line}")
        entries.append(e)
    return blocks, entries


def nplurals(path):
    m = re.search(r"nplurals=(\d+)", path.read_text(encoding="utf-8"))
    return int(m.group(1)) if m else 2


def key(e):
    return (e["msgctxt"] or "") + "\x04" + e["msgid"]


def untranslated(e):
    return (not e["obsolete"] and e["msgid"] and any(s == "" for s in e["msgstr"]))


def export(lang, out):
    todo = []
    for catalog in ("native", "pages"):
        path = LOC / catalog / f"{lang}.po"
        _, entries = parse(path)
        n = nplurals(path)
        for e in entries:
            if untranslated(e):
                todo.append({"catalog": catalog, "key": key(e), "msgctxt": e["msgctxt"], "msgid": e["msgid"],
                             "msgid_plural": e["msgid_plural"],
                             "comments": [c for c in e["comments"] if c.startswith("#.")],
                             "nplurals": n if e["msgid_plural"] is not None else 1,
                             "msgstr": [], "review": ""})
    Path(out).write_text(json.dumps(todo, ensure_ascii=False, indent=1), encoding="utf-8")
    print(f"{lang}: {len(todo)} entries -> {out}")


PLACEHOLDER = re.compile(r"%\d+%|%[sd]|\{[A-Za-z0-9_]+\}|<\d+>|</\d+>|#")


def check(item, text):
    want = sorted(PLACEHOLDER.findall(item["msgid"]))
    got = sorted(PLACEHOLDER.findall(text))
    if item["catalog"] == "native":
        want = [w for w in want if w != "#"]
        got = [g for g in got if g != "#"]
    return want == got or item["msgid_plural"] is not None


def fill(lang, src):
    items = {i["catalog"] + "\x05" + i["key"]: i for i in json.loads(Path(src).read_text(encoding="utf-8"))}
    problems = []
    for catalog in ("native", "pages"):
        path = LOC / catalog / f"{lang}.po"
        blocks, entries = parse(path)
        for e in entries:
            if not untranslated(e):
                continue
            item = items.get(catalog + "\x05" + key(e))
            if item is None or not item["msgstr"] or any(not s for s in item["msgstr"]):
                problems.append(f"missing: {catalog} {e['msgid']!r}")
                continue
            if len(item["msgstr"]) != len(e["msgstr"]):
                problems.append(f"plural forms {len(item['msgstr'])} != {len(e['msgstr'])}: {e['msgid']!r}")
                continue
            if e["msgid_plural"] is None and not check(item, item["msgstr"][0]):
                problems.append(f"placeholders: {e['msgid']!r} -> {item['msgstr'][0]!r}")
                continue
            if e["msgid"].count("\n") != item["msgstr"][0].count("\n"):
                problems.append(f"line breaks: {e['msgid']!r}")
                continue
            comments = [c for c in e["comments"] if c not in ("# AI Translated",) and not c.startswith("# Needs human review")]
            translator = ["# AI Translated"] + ([f"# Needs human review: {item['review']}"] if item.get("review") else [])
            lines = translator + comments
            if e["msgctxt"] is not None:
                lines.append("msgctxt " + quote(e["msgctxt"]))
            lines.append("msgid " + quote(e["msgid"]))
            if e["msgid_plural"] is not None:
                lines.append("msgid_plural " + quote(e["msgid_plural"]))
                for n, s in enumerate(item["msgstr"]):
                    lines.append(f"msgstr[{n}] " + quote(s))
            else:
                lines.append("msgstr " + quote(item["msgstr"][0]))
            # Keep a leading newline when the block had one (the first block).
            lead = "\n" if blocks[e["index"]].startswith("\n") else ""
            blocks[e["index"]] = lead + "\n".join(lines)
        path.write_text("\n\n".join(blocks), encoding="utf-8")
    if problems:
        print(f"{lang}: {len(problems)} problems")
        for p in problems:
            print("  " + p)
        sys.exit(1)
    print(f"{lang}: filled")


if __name__ == "__main__":
    {"export": export, "fill": fill}[sys.argv[1]](sys.argv[2], sys.argv[3])

